function registerDesignSystemAuditTool(server, getDesignSystemData, getCurrentUrl) {
  server.tool("figma_audit_design_system_report", "Run the design-system health audit and return the scored report as data (no UI required). Same deterministic engine as the Design System Dashboard app: naming & semantics, token architecture, component metadata, accessibility, consistency, coverage \u2014 each 0-100 plus a weighted overall. Start with the default summary, then drill into one category at a time via `category` (chunked; avoids one giant payload). Results are cached ~5 minutes; pass forceRefresh after editing the file. Every finding includes whether this MCP can fix it (design-side write tools vs. design decision vs. manual).", {
    fileUrl: external_exports.string().url().optional().describe("Figma file URL. If not provided, uses the currently active file."),
    format: external_exports.enum(["summary", "full"]).optional().default("summary").describe("'summary' (default) \u2014 bounded readable report: overall + category scores + non-pass findings + remediation. 'full' \u2014 complete scored JSON (examples/locations clamped); prefer per-category calls over 'full' when working interactively."),
    category: external_exports.enum([
      "naming-semantics",
      "token-architecture",
      "component-metadata",
      "accessibility",
      "consistency",
      "coverage"
    ]).optional().describe("Return full findings (including passes, examples, locations) for ONE category \u2014 the chunked drill-down path after a summary call."),
    forceRefresh: external_exports.boolean().optional().default(false).describe("Bypass the 5-minute audit cache and re-crawl the file. Only needed after editing the file.")
  }, async ({ fileUrl, format: format2, category, forceRefresh }) => {
    try {
      lastFileUrl = fileUrl || getCurrentUrl?.() || lastFileUrl;
      const data = await getDesignSystemData(fileUrl, forceRefresh);
      const scored = scoreDesignSystem(data);
      const clampFinding = (f2) => ({
        ...f2,
        examples: f2.examples?.slice(0, 5),
        locations: f2.locations?.slice(0, 10)
      });
      const sourceNote = () => {
        const src = scored.dataAvailability?.componentsSource;
        if (src === "rest-published") {
          return "Component data came from the PUBLISHED library snapshot (Desktop Bridge unavailable) \u2014 scores reflect the last publish, not unpublished edits.";
        }
        if (src === "none") {
          return "No component data was available (bridge disconnected and nothing published) \u2014 component-based checks defaulted to passing and are NOT meaningful.";
        }
        return null;
      };
      const remediationLines = (findings) => {
        const lines2 = [];
        for (const f2 of findings) {
          if (f2.severity === "pass" || f2.severity === "info")
            continue;
          const rem = getRemediation(f2.id);
          if (!rem)
            continue;
          lines2.push(`  - ${f2.label}: ${describeFixability(rem.fixability)} \u2014 ${rem.how} [${rem.tools.join(", ")}]`);
        }
        return lines2;
      };
      if (category) {
        const cat = scored.categories.find((c) => c.id === category);
        if (!cat) {
          return {
            content: [
              {
                type: "text",
                text: `Unknown category '${category}'. Valid: ${scored.categories.map((c) => c.id).join(", ")}`
              }
            ],
            isError: true
          };
        }
        const payload = {
          file: scored.fileInfo?.name,
          overall: scored.overall,
          category: {
            ...cat,
            findings: cat.findings.map((f2) => ({
              ...clampFinding(f2),
              remediation: getRemediation(f2.id)
            }))
          },
          componentsSource: scored.dataAvailability?.componentsSource
        };
        return {
          content: [
            { type: "text", text: JSON.stringify(payload) }
          ]
        };
      }
      if (format2 === "full") {
        const clamped = {
          ...scored,
          categories: scored.categories.map((c) => ({
            ...c,
            findings: c.findings.map((f2) => ({
              ...clampFinding(f2),
              remediation: getRemediation(f2.id)
            }))
          }))
        };
        return {
          content: [
            { type: "text", text: JSON.stringify(clamped) }
          ]
        };
      }
      const lines = [];
      const fileName = scored.fileInfo?.name || "Unknown file";
      lines.push(`Design System: ${fileName} \u2014 Overall Health: ${scored.overall}/100 (${scored.status})`);
      const allFindings = [];
      for (const c of scored.categories) {
        lines.push(`
${c.label}: ${c.score}/100 (weight ${c.weight})`);
        for (const f2 of c.findings) {
          allFindings.push(f2);
          if (f2.severity === "pass")
            continue;
          lines.push(`  [${f2.severity.toUpperCase()}] ${f2.label} (${f2.score}): ${f2.details ?? ""}`);
          if (f2.examples?.length) {
            lines.push(`    e.g. ${f2.examples.slice(0, 3).join(" | ")}`);
          }
        }
      }
      if (scored.summary.length) {
        lines.push("\nTop actions:");
        for (const s2 of scored.summary)
          lines.push(`  - ${s2}`);
      }
      const remLines = remediationLines(allFindings);
      if (remLines.length) {
        lines.push("\nRemediation \u2014 what this MCP can fix:");
        lines.push(...remLines);
        lines.push("  Ask the agent to apply any of the design-side fixes above; 'design decision' items need your choice first (the agent can propose options).");
      }
      const note = sourceNote();
      if (note)
        lines.push(`
Data source: ${note}`);
      if (scored.dataAvailability && !scored.dataAvailability.variables) {
        lines.push("\nNote: variable/token data was unavailable (connect the Desktop Bridge plugin or use an Enterprise REST token) \u2014 Token Architecture reflects missing data, not actual quality.");
      }
      lines.push("\nTip: call again with category=<id> for full findings on one dimension (chunked; cached, no re-crawl within 5 min).");
      return {
        content: [{ type: "text", text: lines.join("\n") }]
      };
    } catch (error2) {
      const errorMessage = error2 instanceof Error ? error2.message : String(error2);
      return {
        content: [
          {
            type: "text",
            text: `Design system audit error: ${errorMessage}`
          }
        ],
        isError: true
      };
    }
  });
}

